#!/bin/bash
# Ventana del Mac 1.40.0 (Swift): lo mismo que la de Linux 1.56. Actualizaciones (el primer arranque del
# día y después cada UPDATE_EVERY), botones del visor a tu gusto (el mismo fichero, los mismos botones y
# estilos que Linux), lo que gasta Nexum arriba, la página que sube al cargar un proyecto y los proyectos
# nuevos de Docker con el Apache de Docker. Uso: mac-ventana-140.sh <lvm-instalador.sh del Mac>
SRC=$1 HERE=$(cd "$(dirname "$0")" && pwd)
. "$HERE/comun.sh"
LINUX=$HERE/../lvm-instalador.sh
grep -q "LVM_SWIFT" "$SRC" && grep -q "^func updateCheckDue() -> Bool {" "$SRC" || { echo "  ok    (sin la ventana 1.40 del Mac)"; exit 0; }

# Actualizaciones
check "actualizaciones: siempre al abrir, otra vez al volver si hace rato y cada pocas horas (1.57.51)" 'grep -q "autoCheckUpdates(components: true)" "$SRC" && grep -q "if components && updateCheckDue() {" "$SRC" && grep -qF "queue: .main) { [weak self] _ in self?.updateRecheck() }" "$SRC" && grep -q "withTimeInterval: UPDATE_RECHECK_OPEN, repeats: true" "$SRC" && grep -qF "if auto && self.updateDeclined.contains(u[1]) { return }" "$SRC"' 
check "actualizaciones: cada tantos arranques como en Linux, en el mismo fichero" '[ "$(grep -oP "^let UPDATE_EVERY = \K[0-9]+" "$SRC")" == "$(grep -oP "^UPDATE_EVERY = \K[0-9]+" "$LINUX")" ] && grep -q "\"/actualizaciones-arranques\"" "$SRC"'
# Botones del visor
mac_keys=$(grep -A6 "^let VISOR_BUTTONS:" "$SRC" | grep -oP '\("\K[a-z]+(?=", "[^"]+"\))' | tr '\n' ' ')
lin_keys=$(sed -n "/^VISOR_BUTTONS = /,/\]$/p" "$LINUX" | grep -oP '\("\K[a-z]+(?=", "[^"]+", \()' | tr '\n' ' ')
check "botones: los mismos que en Linux y en el mismo orden ($mac_keys)" '[ -n "$mac_keys" ] && [ "$mac_keys" == "$lin_keys" ]'
check "botones: los mismos estilos y tamaños que en Linux" 'grep -qF "(\"nombre\", \"Icono y nombre en horizontal (solo en el visor clásico)\")," "$SRC" && grep -qF "(\"icono\", \"Solo el icono (cuadrado)\"), (\"grande\", \"Icono y nombre (cuadrado)\")]" "$SRC" && grep -qF "(\"nombre\", \"Icono y nombre en horizontal (solo en el visor clásico)\")," "$LINUX" && grep -q "let VISOR_SIZES: \[String: Int\] = \[\"icono\": 44, \"grande\": 88\]" "$SRC" && grep -q "^BUTTON_SIZES = {\"icono\": 44, \"grande\": 88}" "$LINUX"' 
check "botones: el mismo fichero que en Linux" 'grep -q "let VISOR_FILE = LOG_DIR + \"/botones-visor\"" "$SRC"'
check "logotipos (1.57.25): cada uno ajustado a su contorno; phpMyAdmin en dos colores" 'grep -q "let b = LOGO_BOX_FOR\[d\] ?? (0, 0, 24, 24)" "$SRC" && grep -q "let extra = Swift.min(LOGO_OVER, (long / short).squareRoot())" "$SRC" && grep -q "\"phpmyadmin\": \[(\"M 5.463" "$SRC" && grep -q "struct BrandLogo: View {" "$SRC" && ! grep -q "LogoShape(d: LOGO_PATHS\[\"phpmyadmin\"\] ?? \"\").fill(brand(" "$SRC"'
check "botones: los tres visores colocan sus botones con lo elegido (arriba, también Correo y Terminal; ⋮, el último)" '[ "$(grep -c "let items = model.loadedItems(x, p, c)" "$SRC")" -eq 1 ] && grep -q "let items = visorItems(p, g, up)" "$SRC" && [ "$(grep -c "ForEach(c.order.filter { !c.hidden.contains(\$0) && items\[\$0\] != nil }" "$SRC")" -eq 2 ] && grep -qF "let keys = c.order.filter { !c.hidden.contains(\$0) && (items[\$0] != nil || \$0 == \"correo\" || \$0 == \"terminal\") }" "$SRC"' 
check "botones: Unlink, ⋮, Versiones de PHP y Arrancar o Parar, con el mismo estilo" 'grep -q "VisorButton(conf: c, name: \"Unlink\"" "$SRC" && ! grep -q "name: \"Desmontar\"" "$SRC" && grep -q "VisorButton(conf: model.visorConf, name: \"Más\"" "$SRC" && grep -q "VisorButton(conf: c, name: \"Versiones de PHP…\"" "$SRC" && grep -q "VisorButton(conf: c, name: up ? \"Parar\" : \"Arrancar\"" "$SRC"'
check "botones: sin nombre, igual de alto que de ancho" 'grep -q "\.frame(width: side, height: side)" "$SRC"'
check "botones: «Personalizar los botones…» en el menú ⋮ y en Configuración, con vista previa" 'grep -q "(\"Personalizar los botones…\", { self.panel = .buttons })" "$SRC" && grep -q "Button(\"Personalizar…\") { model.panel = .buttons }" "$SRC" && grep -q "case .buttons:" "$SRC" && grep -q "Text(\"Así quedan\")" "$SRC"'
# Lo que gasta Nexum, arriba
check "consumo: CPU y RAM en el recuadro de arriba, cada 3 s y fuera de la interfaz" 'grep -q "usageText()" "$SRC" && grep -q "Timer.scheduledTimer(withTimeInterval: 3, repeats: true)" "$SRC" && grep -q "DispatchQueue.global(qos: .utility).async" "$SRC"'
# Al cargar un proyecto
check "al cargar un proyecto, la página sube sola hasta el visor" 'grep -q "self.scrollTop += 1" "$SRC" && grep -q "SplitPage(width: Swift.max(980, model.projectsTableWidth), top: model.scrollTop, head:" "$SRC" && grep -q "proxy.scrollTo(\"arriba\", anchor: .top)" "$SRC"'
# Docker
check "Docker: los proyectos nuevos, con el Apache de Docker (formulario y desde Proyectos)" '[ "$(grep -c "\[\"docker-nuevo\", " "$SRC")" -eq 2 ] && ! grep -q "\[\"docker-crear\", " "$SRC"'
check "Docker: la franja del Apache de Docker (Permitir, Arrancar o Parar) y su apartado en Configuración" 'grep -q "webStrip(k)" "$SRC" && grep -q "dockerCard()" "$SRC" && grep -q "model.dockerWebCommand(\"permitir\")" "$SRC"'
check "Docker: versiones de PHP y pasar los de antes" 'grep -q "\[\"docker-php-anadir\", p.slug, v\]" "$SRC" && grep -q "\[\"docker-pasar\", p.slug\]" "$SRC"'
check "Docker: XAMPP-X parado solo avisa con proyectos de antes" 'grep -q "if !k.xampp && k.projects.contains(where: { !\$0.isWeb })" "$SRC"'
check "Docker: el DNS de *.docker.test en Configuración y los dominios con su final (docker.local o docker.test)" 'grep -q "model.dockerDNS(!w.dns)" "$SRC" && grep -q "\[\"docker-web\", \"dns\", on ? \"activar\" : \"quitar\"\]" "$SRC" && grep -q "tld: field(f, 6) == \"docker.test\" ? \"docker.test\" : \"docker.local\", dns: field(f, 7) == \"1\")" "$SRC" && ! grep -q "\"pma.docker.local\"" "$SRC"'
check "configuración: página ancha y sus apartados en tarjetas de dos en dos" 'grep -q "^struct TileCard<Content: View>: View {" "$SRC" && [ "$(grep -c "TileCard(" "$SRC")" -ge 10 ] && grep -q "Tile(\"Dirección y puertos\"" "$SRC"'
check "botones: el panel en horizontal (cabe en un portátil)" 'grep -q "case .buttons: return 900" "$SRC" && grep -q "HStack(alignment: .top, spacing: 24) {" "$SRC"'
# (1.57.51) openFolder es de ToolsView: fuera de ella no existe y la ventana no compila (VS Code, Abrir)
check "openFolder solo dentro de ToolsView; fuera, showFolder" '[ -z "$(awk "/^struct ToolsView: View/ {t=1; next} /^(struct|final class|class|extension|func) / {t=0} !t && /openFolder\\(/ {print NR}" "$SRC")" ] && grep -q "Button(\"Abrir\") { showFolder(dir) }" "$SRC"'
# (1.60.0) Visor arriba (Apariencia, como en Linux): los botones del proyecto cargado en la barra de arriba, la
# versión en la de abajo, las versiones de PHP del proyecto en tarjetas; Ajustes y Sistema; Unlink
check "visor arriba: la clave visor del fichero de Apariencia (arriba si falta), leída y guardada" 'grep -qF "var visor = \"arriba\"" "$SRC" && grep -qF "c.visor = (o[\"visor\"] as? String) == \"clasico\" ? \"clasico\" : \"arriba\"" "$SRC" && sed -n "/^func saveLook/,/^}/p" "$SRC" | grep -qF "let visor: String = c.visor == \"clasico\" ? \"clasico\" : \"arriba\"" && grep -qF "\"visor\": \"clasico\" if conf.get(\"visor\") == \"clasico\" else \"arriba\"" "$LINUX"'
check "visor arriba: en Apariencia, Dónde (Arriba o Clásico), con el texto de Linux" 'grep -qF "Tile(\"Dónde\", \"Arriba: en la barra de arriba, a mano desde cualquier pestaña, y la versión de PHP, Apache, MariaDB y el consumo, en la barra de abajo. Clásico: en Proyectos, como antes\")" "$SRC" && grep -qF "items: [(\"arriba\", \"Arriba\"), (\"clasico\", \"Clásico\")]" "$SRC" && grep -qF "\"Dónde van los botones del proyecto cargado y cuáles se ven, en qué orden y cómo\"" "$SRC"'
check "visor arriba: la barra de arriba, clásica tal cual o con TopVisorBar centrado en la ventana y ☰ al final (1.60.0)" 'sed -n "/^struct TopBar: View {/,/^}/p" "$SRC" > "$TMPBASE/tb1.$$" && grep -qF "if model.look.visor == \"clasico\" {" "$TMPBASE/tb1.$$" && grep -qF "classicBar()" "$TMPBASE/tb1.$$" && grep -A1 -F "TopVisorBar()" "$TMPBASE/tb1.$$" | grep -qF ".padding(.horizontal, Swift.max(leftWidth, rightWidth) + 12)" && grep -B2 "^ *menuButton()$" "$TMPBASE/tb1.$$" | grep -q "warnings()" && grep -qF ".frame(minWidth: geo.size.width)" "$SRC"; r=$?; rm -f "$TMPBASE/tb1.$$"; [ $r -eq 0 ]'
check "visor arriba: cuadrados de 56 con iconos de 20, como en Linux, desplazables en horizontal" 'grep -qF "let TOP_VISOR_SIDE: CGFloat = 56" "$SRC" && grep -qF "let TOP_VISOR_ICON: CGFloat = 20" "$SRC" && grep -qF "TOP_VISOR_SIDE, TOP_VISOR_ICON = 56, 20" "$LINUX" && sed -n "/^struct TopVisorBar: View {/,/^}/p" "$SRC" | grep -qF "ScrollView(.horizontal, showsIndicators: false)" && grep -qF "if compact { return TOP_VISOR_SIDE }" "$SRC"'
check "visor arriba: el proyecto con su logotipo (node con package.json) y su nombre entero sin el prefijo, Unlink, Correo, Terminal y ⋮ al final" 'sed -n "/^struct TopVisorBar: View {/,/^}/p" "$SRC" > "$TMPBASE/tvb.$$" && grep -qF "model.openTab(\"proyectos\")" "$TMPBASE/tvb.$$" && grep -qF "Text(x.map { shortProjectName(\$0.name) } ?? \"Sin proyecto\")" "$TMPBASE/tvb.$$" && grep -qF ".tip(x?.name ?? " "$TMPBASE/tvb.$$" && grep -qF "popMenu(model.moreItems(x))" "$TMPBASE/tvb.$$" && grep -qF "if k == \"correo\" {" "$TMPBASE/tvb.$$" && grep -qF "SquareButton(side: TOP_VISOR_SIDE, kind: model.termOpen ? \"marcado\" : \"\")" "$TMPBASE/tvb.$$" && grep -qF "if isFile(\"package.json\") {" "$SRC" && grep -qF "let PROJECT_NAME_PREFIXES = [\"dob-prestashop-\", \"dob-wordpress-\"]" "$SRC" && grep -qF "PROJECT_NAME_PREFIXES = (\"dob-prestashop-\", \"dob-wordpress-\")" "$LINUX" && ! grep -qF "func shortName(" "$SRC"; r=$?; rm -f "$TMPBASE/tvb.$$"; [ $r -eq 0 ]' 
check "visor arriba: la versión en la barra de estado (sin recuadro, sus recuadros hacia arriba)" 'sed -n "/^struct StatusBar: View {/,/^}/p" "$SRC" | grep -qF "VersionVisor(bottom: true)" && grep -qF "let edge: Edge = bottom ? .top : .bottom" "$SRC" && grep -qF ".popover(isPresented: \$servicesOpen, arrowEdge: edge)" "$SRC" && grep -qF ".popover(isPresented: \$powerOpen, arrowEdge: edge)" "$SRC"'
check "visor arriba: en Proyectos, la cabecera clásica sin los botones (otra versión, con «+ Nueva versión»), sin tarjetas" 'grep -qF "OutlineMenu(\"Nueva versión\", symbol: \"plus\") {" "$SRC" && ! grep -qF "Montar en otra versión de PHP…" "$SRC" && grep -qF "moreMenu(x, square: isLoaded && model.look.visor == \"clasico\")" "$SRC" && grep -qF "func replicate(_ project: Project? = nil) {" "$SRC" && ! grep -qE "heroCards|VersionTile|target wanted" "$SRC" && grep -qF "return self.nv_menu_button(\"Nueva versión\", \"list-add-symbolic\", [" "$LINUX"' 
check "Actualizar código… en el ⋮ de cada fila: el mismo diálogo y el mismo camino, solo con el código" 'grep -qF "Button(\"Actualizar código…\") { model.upOpenCode(x) }" "$SRC" && grep -qF "Text(\"Solo el código: el proyecto no se carga y su BBDD no se toca.\")" "$SRC" && grep -qF "let can: Bool = only ? hasCode :" "$SRC" && grep -qF "let folder = upFolder, sql = only ? \"\" : upSql, db = only ? \"\" : upDb.trimmingCharacters(in: .whitespaces)" "$SRC" && grep -qF "(\"Actualizar código…\", lambda: self.nv_update_code(x))" "$LINUX"'
check "Docker: el visor de los que están en marcha, sin desplegarlos" 'grep -qF "if let p = g.project, open || up {" "$SRC"'
check "Ajustes y Sistema en lugar de Configuración, y cada apartado en la suya" 'grep -qF "(\"ajustes\", \"Ajustes\", \"gearshape\")" "$SRC" && grep -qF "(\"sistema\", \"Sistema\", \"desktopcomputer\")" "$SRC" && grep -qF "case \"ajustes\", \"sistema\": ToolsView()" "$SRC" && grep -qF "let key = key == \"config\" ? configTabOf(toolsSection) : key" "$SRC" && ! grep -qF "tab = \"config\"" "$SRC" && grep -qF "(Proyectos, Ajustes y Sistema salen siempre)" "$SRC"'
check "Unlink: su nombre y su mensaje, como en Linux; ⋮ cuadrado, sin «Más»" 'grep -qF "let UNLINK_TIP = \"Unlink: desmontar el proyecto (web.local deja de apuntar a él)\"" "$SRC" && grep -qF "\"Unlink: desmontar el proyecto (web.local deja de apuntar a él)\"" "$LINUX" && [ "$(grep -c "if name != \"Más\"" "$SRC")" -ge 2 ]'
check "visor arriba: con «Solo el icono», sin el nombre y con el icono de 24 (también Correo y Terminal), como en Linux" 'grep -qF "VisorIconView(icon: icon, size: conf.style == \"icono\" ? TOP_VISOR_ICON + 4 : TOP_VISOR_ICON)" "$SRC" && grep -qF "if name != \"Más\" && conf.style != \"icono\" {" "$SRC" && [ "$(sed -n "/^struct TopVisorBar: View {/,/^}/p" "$SRC" | grep -c "let named = model.visorConf.style != \"icono\"")" -eq 2 ] && grep -qF "TOP_VISOR_ICON + (4 if conf.get(\"sin_nombre\") else 0)" "$LINUX" && sed -n "/^    func saveVisor/,/^    }/p" "$SRC" | grep -qF "visorConf = c"'
# (1.60.0) Iconos de Reicon (MIT) en lugar de los SF Symbols que tienen equivalente, iguales que en Linux; el
# logotipo del tipo de proyecto (Simple Icons, CC0), detectado como en Linux; y Ajustes o Sistema en los textos
check "iconos: los de Reicon, con su licencia MIT, y los mismos que Linux (carpeta, papelera, ⋮ girado, ▶ y ■ rellenos)" 'grep -qF "// Copyright (c) 2025 REICON" "$SRC" && grep -qF "\"ellipsis\": \"more-h@90\"" "$SRC" && grep -qF "\"view-more-symbolic\": \"more-h@90\"" "$LINUX" && grep -qF "\"folder\": \"folder\"" "$SRC" && grep -qF "\"trash\": \"trash2\"" "$SRC" && grep -qF "\"user-trash-symbolic\": \"trash2\"" "$LINUX" && grep -qF "\"play.fill\": \"play!f\"" "$SRC" && grep -qF "\"stop.fill\": \"stop!f\"" "$SRC" && grep -qF "ReiconShape(d: parts[i].d).fill(style: FillStyle(eoFill: parts[i].eo))" "$SRC"'
check "iconos: cada nombre de Reicon que se usa tiene sus trazos" 'python3 -I -c "
import re, sys
t = open(sys.argv[1], encoding=\"utf-8\").read()
m = t[t.index(\"let REICON_FOR_SF: [String: String] = [\"):t.index(\"let REICON_PATHS:\")]
names = {v.split(\"@\")[0] for v in re.findall(r\": \\\"([a-z0-9!@-]+)\\\"\", m)}
have = set(re.findall(r\"^    \\\"([a-z0-9!-]+)\\\": \\\"[EN]\\|M \", t, re.M))
sys.exit(0 if names and names <= have else 1)
" "$SRC"'
check "iconos: la etiqueta de los menús, con imagen de plantilla; los demás, UIIcon (sin Image(systemName:) sueltos)" 'grep -qF "Label { Text(t) } icon: { uiIconImage(symbol, size: 16) }" "$SRC" && grep -qF "img.isTemplate = true" "$SRC" && [ "$(sed -n "/^    cat <<.LVM_SWIFT.$/,/^LVM_SWIFT$/p" "$SRC" | grep -c "Image(systemName:")" -le 3 ]'
check "logotipos del tipo de proyecto: los 12 de Simple Icons, con su color claro y oscuro, y la misma detección que Linux" 'for k in astro laravel symfony nextdotjs nuxtdotjs vuedotjs react svelte angular drupal joomla magento; do grep -q "^    \"$k\": \"M " "$SRC" || exit 1; grep -q "\"$k\": dynamicHex(" "$SRC" || exit 1; done; grep -qF "LOGO_PATHS_BASE.merging(FRAMEWORK_PATHS" "$SRC" && grep -qF "if isFile(\"artisan\") || req.contains(\"laravel/framework\") { return \"laravel\" }" "$SRC" && grep -qF "(\"@sveltejs/kit\", \"svelte\")" "$SRC" && grep -qF "(\"@sveltejs/kit\", \"svelte\")" "$LINUX" && grep -qF "Simple Icons 13.21.0 (https://simpleicons.org), CC0" "$SRC"'
check "textos: Ajustes o Sistema, ya no Configuración" 'grep -qF "Button(\"Ir a Ajustes\")" "$SRC" && grep -qF "siguen en Sistema, General, Parches nuevos." "$SRC" && grep -qF "toast(\"Instala Mailpit en Ajustes, apartado Correo de pruebas\")" "$SRC" && ! grep -qF "Ir a Configuración" "$SRC" && ! grep -qF "(conéctalo en Configuración" "$SRC"'
check "registros: las listas de ~/.nexum/listas, enlaces que solo abren un fichero de esa carpeta (consola y Registro de tareas)" 'grep -qF "let LISTS_LINK_RX = try! NSRegularExpression(pattern: NSRegularExpression.escapedPattern(for: LISTS_DIR) + \"/[^\\\\s/]+\\\\.txt\")" "$SRC" && grep -qF "guard real.hasPrefix(dir + \"/\"), real.hasSuffix(\".txt\")," "$SRC" && grep -qF "func textView(_ textView: NSTextView, clickedOnLink link: Any, at charIndex: Int) -> Bool {" "$SRC" && [ "$(grep -c "setupListLinks(tv)" "$SRC")" -eq 2 ] && grep -qF "ConsoleTextView(log: log, toEnd: toEnd)" "$SRC" && grep -qF "LISTS_LINK_RE = re.compile(" "$LINUX"'
check "Personalizar: Unlink, Correo y Terminal se eligen y se ordenan (en una configuración de antes, al final); ⋮ al final de la vista previa" 'grep -qF "(\"unlink\", \"Unlink\"), (\"correo\", \"Correo\"), (\"terminal\", \"Terminal\")]" "$SRC" && grep -qF "if VISOR_LATE_KEYS.contains(k) {" "$SRC" && grep -qF "if k not in order and k in (\"unlink\", \"correo\", \"terminal\"):" "$LINUX" && grep -qF "⋮, el último, y los propios de Docker (Versiones de PHP, Arrancar o Parar) se ven siempre. Unlink es solo del proyecto cargado, y Correo y Terminal, del visor de arriba." "$SRC" && ! grep -qF "VisorButton(conf: conf, name: \"Unlink\"" "$SRC"'
check "⋮ del cargado sin las imágenes de producción (ya tienen su botón)" 'grep -qF "if !loaded && (x.kind == \"ps\" || x.kind == \"wp\") {" "$SRC" && grep -qF "if !loaded && x.kind == \"ps\" {" "$SRC"'
check "iconos de Actualizar, Log y Unlink: dos a elegir en Apariencia, como en Linux, guardados en «iconos»" 'grep -qF "let VISOR_ICON_CHOICES: [String: (String, String)] = [\"actualizar\": (\"upload\", \"refresh-circle\")," "$SRC" && grep -qF "\"log\": (\"file-text\", \"code-file\")," "$SRC" && grep -qF "\"unlink\": (\"link-broken\", \"logout\")]" "$SRC" && grep -qF "\"nexum-actualizar-2-symbolic\": \"refresh-circle\"" "$LINUX" && for k in upload refresh-circle file-text code-file link-broken logout; do grep -q "^    \"$k\": \"[EN]|M " "$SRC" || exit 1; done; grep -qF "Tile(\"Iconos\", \"Los de Actualizar, Log y Unlink\")" "$SRC" && grep -qF "let iconos: [String: Int] = c.iconos.filter {" "$SRC" && [ "$(grep -c "visorChoice(\"log\", model.look.iconos)" "$SRC")" -eq 3 ]'
check "rapidez: sin transiciones al pasar el ratón ni al cambiar de página; lo que se desliza, 0,09 s; VS Code y el repositorio, guardados un rato" '! grep -qF ".animation(.easeOut(duration: 0.12)" "$SRC" && ! grep -q "duration: 0.35" "$SRC" && grep -qF "let UI_ANIM: Double = 0.09" "$SRC" && grep -qF "repeatForever(autoreverses: true)) { dim = true }" "$SRC" && grep -qF "repeatForever(autoreverses: true)) { pulse = true }" "$SRC" && grep -qF "if let c = repoURLCache[folder], Date().timeIntervalSince(c.0) < 30 { return c.1 }" "$SRC" && grep -qF "if Date().timeIntervalSince(vscodeCache.0) < 30 { return vscodeCache.1 }" "$SRC" && ! grep -qF "NSWorkspace.shared.icon(forFile: code.path)))" "$SRC"'
check "Avisos: justo a la izquierda de ☰ en los dos visores, plano (sin recuadro) y siempre del mismo tamaño" 'sed -n "/^struct TopBar: View {/,/^}/p" "$SRC" > "$TMPBASE/tb.$$" && [ "$(grep -A1 "^ *warnings()$" "$TMPBASE/tb.$$" | grep -c "^ *menuButton()$")" -eq 2 ] && grep -B6 "^ *warnings()$" "$TMPBASE/tb.$$" | grep -q "TaskBadge(task: t)" && grep -A14 "Button(action: { warnOpen.toggle() })" "$TMPBASE/tb.$$" | grep -qF ".buttonStyle(PlainButtonStyle())" && grep -qF ".fill(Color.primary.opacity(warnHover || warnOpen ? 0.10 : 0))" "$TMPBASE/tb.$$"; r=$?; rm -f "$TMPBASE/tb.$$"; [ $r -eq 0 ]'
check "versión de PHP: al pulsarla, «Cambiar de versión de PHP» con las instaladas en abanico (activa marcada, las demás se activan)" 'grep -qF ".tip(\"Cambiar de versión de PHP\")" "$SRC" && grep -qF "VersionsFan(fromBottom: bottom, close: { versionsOpen = false })" "$SRC" && grep -qF ".popover(isPresented: \$versionsOpen, arrowEdge: edge)" "$SRC" && grep -qF "Text(running ? \"● en marcha\" : \"● activa\")" "$SRC" && grep -qF "DispatchQueue.main.async { model.activate(i.folder) }" "$SRC" && grep -qF "let delay: Double = 0.028 * Double(step)" "$SRC" && grep -qF "withAnimation(.easeOut(duration: 0.15).delay(delay)) { shown = true }" "$SRC" && grep -qF "\$0.php.compare(\$1.php, options: .numeric) == .orderedDescending" "$SRC"'
check "botones cuadrados: «PMA» e «Imágenes» si el nombre entero no cabe (medido con su letra), como en Linux" 'grep -qF "let SQUARE_SHORT_NAMES: [String: String] = [\"phpMyAdmin\": \"PMA\", \"Imágenes de producción\": \"Imágenes\"]" "$SRC" && grep -qF "SQUARE_SHORT_NAMES = {\"phpMyAdmin\": \"PMA\", \"Imágenes de producción\": \"Imágenes\"}" "$LINUX" && grep -qF "size(withAttributes: [.font: NSFont.systemFont(ofSize: fontSize)]).width" "$SRC" && [ "$(grep -c "Text(squareName(name, conf.side - " "$SRC")" -eq 2 ]'
check "iconos en color: los de los botones por su función (los mismos colores que Linux) y los demás, uno del logotipo de Nexum" 'grep -qF "let ICON_TINT_COLORS: [String: UInt32] = [\"verde\": 0x2EA043, \"rojo\": 0xE5534B, \"azul\": 0x2F81F7, \"naranja\": 0xF0883E," "$SRC" && grep -qF "\"amarillo\": 0xD4A300, \"morado\": 0xA371F7, \"turquesa\": 0x1F9E95]" "$SRC" && grep -qF "let NEXUM_TINTS: [UInt32] = [0x006CB7, 0x88BB1D, 0xFFB608, 0xFF3B3B, 0xF20093]" "$SRC" && grep -qF ".environment(\\.iconsTinted, model.look.color)" "$SRC" && grep -qF "UIIcon(s, size: size * 0.77).foregroundColor(iconColor(s, c))" "$SRC" && grep -qF "TintIcon(\"terminal\", size: side * 0.8)" "$SRC" && [ "$(grep -c "icon: { TintIcon(" "$SRC")" -ge 8 ] && ! grep -q "TintIcon(icon" "$SRC"'
check "Repositorios: «Clonar» tan ancho como «Traer cambios»" '[ "$(grep -c "Text(\"Clonar\").frame(minWidth: CLONE_WIDTH)" "$SRC")" -eq 2 ] && grep -qF "let CLONE_WIDTH: CGFloat = ceil((\"Traer cambios\" as NSString).size(withAttributes:" "$SRC"'
check "Correo: si Mailpit está parado con la versión en marcha, se arranca al pulsarlo (correo arrancar) y se abre, sin bucles" 'grep -qF "runQuick([\"correo\", \"arrancar\"]) { rc, _ in" "$SRC" && grep -qF "self.openMail(retried: true)" "$SRC" && grep -qF "} else if !m.running && retried {" "$SRC" && grep -qF "toast(\"No se ha podido arrancar Mailpit: mira Ajustes, Correo de pruebas\")" "$SRC" && grep -qF "toast(\"Arrancando Mailpit…\")" "$SRC"'
check "ventanas del programa: nunca más grandes que la principal menos 80 (ni que la pantalla), como en Linux" 'grep -qF "let DIALOG_MARGIN: CGFloat = 80" "$SRC" && grep -qF "func dialogMax() -> CGSize {" "$SRC" && grep -qF "if let acc = accessoryView {" "$SRC" && [ "$(grep -c "\.frame(width: dialogWidth(" "$SRC")" -ge 5 ] && [ "$(grep -c "\.fitDialog()" "$SRC")" -ge 5 ] && ! grep -qE "NSRect\(x: 0, y: 0, width: (720|760), height: 560\)" "$SRC"'
check "al abrirse, lo último que leyó (gui-datos, hosts, servicios, proyectos, docker), sin preguntas; se guarda en la cola de fondo, 0700/0600, solo si cambia" 'grep -qF "let DATA_CACHED: Set<String> = [\"gui-datos\", \"gui-hosts\", \"gui-servicios\", \"gui-proyectos\", \"gui-docker\"]" "$SRC" && grep -qF "DATA_CACHED = (\"gui-datos\", \"gui-hosts\", \"gui-servicios\", \"gui-proyectos\", \"gui-docker\")" "$LINUX" && grep -qF "let DATA_CACHE_DIR = LOG_DIR + \"/cache/ventana\"" "$SRC" && grep -qF "if p.terminationStatus == 0 && args.count == 1 && env.isEmpty && input == nil {" "$SRC" && grep -qF "attributes: [.posixPermissions: 0o600])" "$SRC" && grep -qF "if dataCacheRead(cmd) == out { return }" "$SRC" && grep -qF "guard !SIMULATE, DATA_CACHED.contains(cmd)," "$SRC" && grep -B2 "^        reload(branches: true)$" "$SRC" | grep -qF "loadDataCache()" && grep -A1 -F "if d != data { data = d }" "$SRC" | grep -qF "if cached { return }"'
exit $fail
